def backfill_start_dates(apps, schema_editor):
    """Việc cũ: bắt đầu = hạn của mốc liền trước trong cùng kế hoạch (mốc đầu = ngày tạo kế hoạch)."""
    from datetime import timedelta

    Plan = apps.get_model('ra_mat_sp', 'LaunchPlan')
    Task = apps.get_model('ra_mat_sp', 'LaunchTask')
    for plan in Plan.objects.all():
        tasks = list(Task.objects.filter(plan=plan, start_date__isnull=True))
        if not tasks:
            continue
        offsets = sorted({t.offset_days for t in Task.objects.filter(plan=plan)})
        created = plan.created_at.date() if plan.created_at else plan.launch_date
        starts, prev = {}, None
        for offset in offsets:
            due = plan.launch_date + timedelta(days=offset)
            start = plan.launch_date + timedelta(days=prev) if prev is not None else min(created, due)
            starts[offset] = min(start, due)
            prev = offset
        for t in tasks:
            t.start_date = min(starts.get(t.offset_days, t.due_date), t.due_date)
            t.save(update_fields=['start_date'])


